import hashlib,json
import pymysql

def query(conn,sql,args=None):
    with conn.cursor() as cursor:
        cursor.execute(sql,args)
        return cursor.fetchall()

def read_history(conn,snapshot_tso,approved_copy,approved_sha256):
    if type(snapshot_tso) is not int or snapshot_tso<=0:
        raise ValueError("positive explicit snapshot TSO required")
    if not isinstance(approved_copy,bytes) or not 0<len(approved_copy)<=65536 or hashlib.sha256(approved_copy).hexdigest()!=approved_sha256:
        raise ValueError("approved export digest mismatch")
    data=json.loads(approved_copy)
    if not isinstance(data,dict) or set(data)!={"version","snapshot_tso","rows"} or type(data["version"]) is not int or data["version"]!=1 or type(data["snapshot_tso"]) is not int or data["snapshot_tso"]!=snapshot_tso:
        raise ValueError("export identity mismatch")
    rows=data["rows"]
    if not isinstance(rows,list) or len(rows)>1000 or any(not isinstance(row,list) or len(row)!=2 or type(row[0]) is not int or not isinstance(row[1],str) or len(row[1])>40 for row in rows):
        raise ValueError("invalid export rows")
    if [row[0] for row in rows]!=sorted({row[0] for row in rows}):
        raise ValueError("duplicate/unordered identities")
    snapshot,autocommit=query(conn,"SELECT @@tidb_snapshot,@@autocommit")[0]
    if snapshot!="" or autocommit!=1:raise ValueError("idle unsnapshotted source connection required")
    try:
        query(conn,"SET @@tidb_snapshot=%s",(str(snapshot_tso),))
        actual=[list(row) for row in query(conn,"SELECT id,value FROM history ORDER BY id")]
        if actual!=rows:raise ValueError("online snapshot and approved export disagree")
        mode="online"
    except pymysql.err.OperationalError as exc:
        message=str(exc).lower()
        if exc.args[0]!=8055 or "snapshot" not in message or "gc safe point" not in message:raise
        mode="verified_export"
    finally:
        query(conn,"SET @@tidb_snapshot=''")
    return {"mode":mode,"snapshot_tso":snapshot_tso,"rows":rows,"copy_sha256":approved_sha256}

def restore_copy(target,loaded):
    # The caller provides a separately verified independent target cluster, never the source.
    if query(target,"SHOW TABLES LIKE 'history'"):raise FileExistsError("target history already exists")
    query(target,"CREATE TABLE history (id BIGINT PRIMARY KEY, value VARCHAR(40))")
    try:
        target.begin()
        for row in loaded["rows"]:query(target,"INSERT INTO history(id,value) VALUES (%s,%s)",row)
        target.commit()
    except Exception:
        target.rollback()
        raise
    actual=[list(row) for row in query(target,"SELECT id,value FROM history ORDER BY id")]
    if actual!=loaded["rows"]:raise ValueError("recovery verification mismatch")
    return {"rows":actual,"snapshot_tso":loaded["snapshot_tso"],"mode":loaded["mode"]}
